### Python

```python
MOD = 998244353
def solve():
    n = int(input().strip())
    if n == 1:
        print(0)
        return
    # 结果 = (n-1) * 2^(n-2) % MOD
    ans = ( (n-1) % MOD ) * pow(2, n-2, MOD) % MOD
    print(ans)

if __name__ == "__main__":
    solve()
```

